<script>document.addEventListener('DOMContentLoaded',function(){const search=document.getElementById('feb-user-search'),list=document.getElementById('feb-user-list'),count=document.getElementById('feb-user-count');if(!search||!list||!count)return;function update(){let n=0;list.querySelectorAll('input[type=checkbox]').forEach(function(box){if(box.checked)n++;});count.textContent=n+' utilisateur'+(n>1?'s':'')+' sélectionné'+(n>1?'s':'');}search.addEventListener('input',function(){const q=search.value.trim().toLocaleLowerCase();list.querySelectorAll('.feb-user-choice').forEach(function(item){item.hidden=!item.textContent.toLocaleLowerCase().includes(q);});});list.addEventListener('change',update);update();});</script>
<style>.feb-user-picker,.feb-role-picker{border:1px solid #d9e3f0;border-radius:12px;padding:16px;margin:18px 0}.feb-user-picker legend,.feb-role-picker legend{font-weight:700;padding:0 8px}.feb-user-picker-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px;max-height:280px;overflow-y:auto;margin-top:12px}.feb-user-choice{display:flex;align-items:center;gap:10px;border:1px solid #e2e8f0;border-radius:10px;padding:10px;cursor:pointer}.feb-user-choice[hidden]{display:none}.feb-user-choice:has(input:checked){background:#eff6ff;border-color:#2563eb}.feb-user-choice input,.feb-role-picker input{width:auto;flex-shrink:0}.feb-user-choice span{display:grid;gap:3px;min-width:0}.feb-user-choice small{overflow-wrap:anywhere;color:#64748b}.feb-role-picker{display:flex;flex-wrap:wrap;gap:18px}.feb-role-picker legend{width:auto}.feb-role-picker label{display:flex;align-items:center;gap:8px}</style>
